// Plot a function, and a background grid.

highp float pi = 3.14159265;

// Fom -2 to 2
highp float scale = 4.0;

#define saturate(x) clamp(x,0.,1.)
#define plainstep(a, b, x) saturate((x-a)/(b-a))

float f(highp float x) {
  float power = pow(256., pow(iMouse.x / iResolution.x, 2.));
  float tmp = pow(abs(x), power);
  return (tmp < 1e38) ? x / pow(1.+tmp, 1./power) : sign(x);
}

// Transform an vec2 onscreen coordinate (0.0-1.0) to a coordinate that
// we want to plot the function for. (+/- scale*2)
vec2 p2v(vec2 pos) {
    pos -= vec2(0.5 * iResolution.x/iResolution.y, 0.5);
    pos *= scale;
    return pos;
}

// Evaluate the function, return 1 if we're above the line.
float t(vec2 pos) {
    pos = p2v(pos);
    if(f(pos.x) > pos.y) {
        return 1.0;
    } else {
        return 0.0;
    }
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
	vec2 uv = fragCoord.xy / iResolution.yy;
    int cnt = 0;
    int max_cnt = 0;
    // 81-point subsampling
    for (float x = -1.0; x <= 1.0; x += 0.25) {
        for (float y = -1.0; y <= 1.0; y += 0.25) {
            max_cnt ++;
            if (1.0 == t((fragCoord.xy + vec2(x, y)) / iResolution.yy))
                cnt ++;
        }
    }
    if (cnt > max_cnt / 2) cnt = max_cnt - cnt;

    float color = float(cnt) * 2.0 / float(max_cnt);
	float bg = 0.0;
    vec2 v = p2v(uv);
	if (abs(v.x) < scale/iResolution.x || abs(v.y) < scale/iResolution.y) {
      bg = 0.0;
    } else {
	    vec2 grid = step(mod(v, vec2(2.0, 2.0)), vec2(1.0, 1.0));
    	if (grid.x == grid.y) {
          bg = 0.2;
        } else {
          bg = 0.14;
        }
    }
    color = mix(bg, 1.0, color); 
    fragColor = vec4(color, color, color, 1.0);
}
